import React from 'react';
import {
    LayoutDashboard,
    MessageSquare,
    FileText,
    Settings,
    Activity
} from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';

const Sidebar = () => {
    const location = useLocation();

    const menuItems = [
        { icon: LayoutDashboard, label: 'Dashboard', path: '/' },
        { icon: MessageSquare, label: 'Chat Agent', path: '/chat' },
        { icon: Activity, label: 'Benchmark', path: '/benchmark' },
        { icon: FileText, label: 'Reports', path: '/reports' }
    ];

    return (
        <div className="
            h-screen w-64 fixed left-0 top-0 z-50 
            bg-gradient-to-b from-[#0a071d] via-[#120c3b] to-[#050816]
            border-r border-white/10 
            backdrop-blur-xl 
            shadow-[4px_0_25px_rgba(0,0,0,0.4)]
            flex flex-col
        ">
            {/* Brand Header */}
            <div className="p-6">
                <h1 className="text-3xl font-bold tracking-wide text-white flex items-center gap-2">
                    <span className="bg-gradient-to-r from-[#7B5CFF] to-[#FF50C8] bg-clip-text text-transparent">
                        WRITE
                    </span>
                    BOT
                </h1>

                <p className="text-xs text-white/60 mt-1">
                    AI News Intelligence
                </p>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-4 mt-6 space-y-2">
                {menuItems.map((item) => {
                    const Icon = item.icon;
                    const isActive = location.pathname === item.path;

                    return (
                        <Link
                            key={item.path}
                            to={item.path}
                            className={`
                                flex items-center gap-3 px-4 py-3 rounded-xl 
                                transition-all duration-200 text-sm font-medium
                                ${
                                    isActive
                                        ? 'bg-white/10 text-white border border-white/20 shadow-lg shadow-primary/30 backdrop-blur-md'
                                        : 'text-white/60 hover:text-white hover:bg-white/5'
                                }
                            `}
                        >
                            <Icon size={20} className={isActive ? 'text-primary' : 'text-white/70'} />
                            <span>{item.label}</span>
                        </Link>
                    );
                })}
            </nav>

            {/* Footer */}
            <div className="p-4 border-t border-white/10">
                <Link
                    to="/settings"
                    className="
                        flex items-center gap-3 px-4 py-3 
                        text-white/60 hover:text-white transition-all rounded-xl
                    "
                >
                    <Settings size={20} className="text-white/70" />
                    <span>Settings</span>
                </Link>
            </div>
        </div>
    );
};

export default Sidebar;
